import { Table } from 'antd';
import { proFieldParsingValueEnumToArray } from "../../field";
import { omitBoolean, omitUndefinedAndEmptyArr, runFunction } from "../../utils";
import { columnRender, defaultOnFilter, renderColumnsTitle } from "./columnRender";
import { genColumnKey, parseProFilteredValue, parseProSortOrder } from "./index";
function resolveOnFilter(columnProps) {
  const {
    onFilter,
    dataIndex
  } = columnProps;
  if (onFilter === true) {
    return (value, row) => defaultOnFilter(value, row, dataIndex);
  }
  return omitBoolean(onFilter);
}
function resolveFilters(columnProps) {
  const {
    filters = [],
    valueEnum
  } = columnProps;
  if (filters === true) {
    return proFieldParsingValueEnumToArray(runFunction(valueEnum, undefined)).filter(valueItem => valueItem && valueItem.value !== 'all');
  }
  return filters;
}
function getColumnConfig(columnsMap, columnKey, columnProps) {
  const config = columnsMap?.[columnKey] || {
    fixed: columnProps.fixed
  };
  return {
    fixed: config.fixed
  };
}
function parseColumnFilterSort(proFilter, proSort, columnProps) {
  return {
    filteredValue: parseProFilteredValue(proFilter, columnProps),
    sortOrder: parseProSortOrder(proSort, columnProps)
  };
}
function updateSubNameRecord(rowData, index, keyName, childrenColumnName, subNameRecord) {
  if (typeof rowData !== 'object' || rowData === null || !Reflect.has(rowData, keyName)) {
    return undefined;
  }
  const record = rowData;
  const uniqueKey = record[keyName];
  const parentInfo = subNameRecord.get(uniqueKey) || [];
  record[childrenColumnName]?.forEach(item => {
    const itemUniqueKey = item[keyName];
    if (!subNameRecord.has(itemUniqueKey)) {
      subNameRecord.set(itemUniqueKey, parentInfo.concat([index, childrenColumnName]));
    }
  });
  return uniqueKey;
}
function createCellRender(columnProps, context, subNameRecord) {
  let keyName = context.rowKey ?? 'id';
  return function cellRender(text, rowData, index) {
    if (typeof context.rowKey === 'function') {
      keyName = context.rowKey(rowData, index);
    }
    const uniqueKey = updateSubNameRecord(rowData, index, keyName, context.childrenColumnName, subNameRecord);
    return columnRender({
      columnProps,
      text,
      rowData,
      index,
      columnEmptyText: context.columnEmptyText,
      counter: context.counter,
      type: context.type,
      marginSM: context.marginSM,
      subName: subNameRecord.get(uniqueKey) ?? [],
      editableUtils: context.editableUtils
    });
  };
}

/**
 * 转化 columns 到 pro 的格式 主要是 render 方法的自行实现
 *
 * @param params.columns 列配置
 * @param params.context 列计算上下文（表级配置与状态）
 * @param params.parents 父列，递归子列时传入
 */
export function genProColumnToColumn(params) {
  const {
    columns,
    context,
    parents
  } = params;
  const subNameRecord = new Map();
  return columns?.map((columnProps, columnsIndex) => {
    if (columnProps === Table.EXPAND_COLUMN) return columnProps;
    if (columnProps === Table.SELECTION_COLUMN) return columnProps;
    const {
      key,
      dataIndex,
      valueEnum,
      valueType = 'text',
      children
    } = columnProps;
    const columnKey = genColumnKey(key || dataIndex?.toString(), [parents?.key, columnsIndex].filter(Boolean).join('-'));
    const noNeedPro = !valueEnum && !valueType && !children;
    if (noNeedPro) {
      return {
        index: columnsIndex,
        ...columnProps
      };
    }
    const {
      filteredValue,
      sortOrder
    } = parseColumnFilterSort(context.proFilter, context.proSort, columnProps);
    const {
      fixed
    } = getColumnConfig(context.counter.columnsMap, columnKey, columnProps);
    const tempColumns = {
      index: columnsIndex,
      key: columnKey,
      ...columnProps,
      title: renderColumnsTitle(columnProps),
      valueEnum,
      filters: resolveFilters(columnProps),
      onFilter: resolveOnFilter(columnProps),
      filteredValue,
      sortOrder,
      fixed,
      width: columnProps.width || (columnProps.fixed ? 200 : undefined),
      children: columnProps.children ? genProColumnToColumn({
        columns: columnProps?.children ?? [],
        context,
        parents: {
          ...columnProps,
          key: columnKey
        }
      }) : undefined,
      render: createCellRender(columnProps, context, subNameRecord)
    };
    return omitUndefinedAndEmptyArr(tempColumns);
  })?.filter(item => !item.hideInTable);
}